package com.gamehub.application.service; import com.gamehub.application.OperationsService; import java.time.Instant; import java.util.List; public final class MatchService { private final OperationsService ops; public MatchService(OperationsService ops){this.ops=ops;} public List<String> matches(long t)throws Exception{return ops.matches(t);} public List<String> participants(long m)throws Exception{return ops.matchParticipants(m);} public List<Long> generate(long a,long t)throws Exception{return ops.generateMatches(a,t);} public void schedule(long a,long m,long s,Instant when)throws Exception{ops.scheduleMatch(a,m,s,when);} public void start(long a,long m)throws Exception{ops.startMatch(a,m);} public void result(long a,long m,int x,int y,long w)throws Exception{ops.recordMatchResult(a,m,x,y,w);} public void correct(long a,long m,int x,int y,long w,String reason)throws Exception{ops.correctMatchResult(a,m,x,y,w,reason);} }